def admit_buy(cash,position,cap,open_orders,request,enabled,age_ms):
    # Own long-only, one-instrument, one-currency, zero-fee BUY reservation model.
    for value,upper in ((cash,10**9),(position,1000),(cap,1000),(age_ms,10**6)):
        if type(value) is not int or not 0<=value<=upper:
            raise ValueError("invalid state scalar")
    if position>cap or type(enabled) is not bool:
        raise ValueError("invalid position or gate")
    if type(open_orders) is not tuple or len(open_orders)>16:
        raise ValueError("invalid bounded reservation list")
    def valid_order(order):
        return (type(order) is tuple and len(order)==3 and
                all(type(x) is int for x in order) and
                1<=order[0]<=10000 and 1<=order[1]<=10000 and 1<=order[2]<=100)
    if not all(valid_order(o) for o in open_orders) or not valid_order(request):
        raise ValueError("invalid order fields")
    ids=[o[0] for o in open_orders]
    if len(set(ids))!=len(ids) or request[0] in ids:
        raise ValueError("duplicate live reservation identity")
    reserved=sum(price*qty for _,price,qty in open_orders)
    exposure=position+sum(qty for _,_,qty in open_orders)
    if reserved>cash or exposure>cap:
        raise ValueError("inconsistent existing reservations")
    if not enabled:return "disabled",open_orders
    if age_ms>100:return "stale",open_orders
    if len(open_orders)==16:return "capacity",open_orders
    _,price,qty=request
    if exposure+qty>cap:return "position",open_orders
    if reserved+price*qty>cash:return "cash",open_orders
    return "reserved",open_orders+(request,)


def sweep_buy(book,limit,quantity):
    # Own static ask-only IOC-like model: (id,price,arrival_rank,remaining_qty).
    if type(limit) is not int or not 1<=limit<=10000 or type(quantity) is not int or not 1<=quantity<=100:
        raise ValueError("invalid incoming order")
    if type(book) is not tuple or len(book)>16:
        raise ValueError("invalid bounded book")
    for row in book:
        if (type(row) is not tuple or len(row)!=4 or not all(type(x) is int for x in row)
            or not 1<=row[0]<=10000 or not 1<=row[1]<=10000
            or not 0<=row[2]<=10000 or not 1<=row[3]<=100):
            raise ValueError("invalid resting row")
    if len({row[0] for row in book})!=len(book):
        raise ValueError("duplicate resting identity")
    ordered=sorted(book,key=lambda row:(row[1],row[2],row[0]))
    unfilled=quantity
    fills=[]
    residual=[]
    cost=0
    for identifier,price,arrival,available in ordered:
        take=min(unfilled,available) if price<=limit else 0
        if take:
            fills.append((identifier,price,take))
            cost+=price*take
            unfilled-=take
        if available>take:residual.append((identifier,price,arrival,available-take))
    return tuple(fills),tuple(residual),unfilled,cost


def replay_sim(events):
    # Pure full replay from fixed initial book/account;NOT an external venue.
    if type(events) is not list or len(events)>16:raise ValueError("invalid bounded command log")
    for index,event in enumerate(events,1):
        if type(event) is not tuple or len(event)!=4:raise ValueError("invalid command shape")
        sequence,kind,price,qty=event
        if type(sequence) is not int or sequence!=index or type(kind) is not str or kind not in ("BUY","OFF","ON"):
            raise ValueError("invalid command sequence or kind")
        if type(price) is not int or type(qty) is not int:raise ValueError("invalid command fields")
        if kind=="BUY":
            if not 1<=price<=10000 or not 1<=qty<=100:raise ValueError("invalid BUY")
        elif price!=0 or qty!=0:raise ValueError("gate command payload")
    cash=1000;position=0;enabled=True
    book=((1,100,0,3),(2,101,1,4))
    outcomes=[]
    for sequence,kind,price,qty in events:
        if kind!="BUY":
            enabled=kind=="ON"
            outcomes.append((sequence,kind))
            continue
        status,_=admit_buy(cash,position,5,(),(sequence,price,qty),enabled,0)
        if status!="reserved":
            outcomes.append((sequence,status))
            continue
        fills,book,unfilled,cost=sweep_buy(book,price,qty)
        acquired=qty-unfilled
        cash-=cost;position+=acquired
        outcomes.append((sequence,"matched",fills,unfilled,cost))
    return cash,position,book,enabled,tuple(outcomes)

commands=[(1,"BUY",100,2),(2,"OFF",0,0),(3,"BUY",101,1),(4,"ON",0,0),(5,"BUY",101,3)]
result=replay_sim(commands)
print(result[:4])
print(result[4])
print(replay_sim(commands)==result)
try:replay_sim(commands+[(7,"BUY",101,1)])
except ValueError as error:print(error)
